        h2: "Статус критично важливого підприємства",
        html: `<p>Бронювання працівників починається не з переліків, а зі статусу. Без рішення про визнання підприємства критично важливим для функціонування економіки та забезпечення життєдіяльності населення бронювати нікого не можна — за винятком окремих категорій, для яких порядок передбачає спеціальні правила (органи влади, підприємства оборонно-промислового комплексу тощо).</p>
<p>Статус надає відповідний державний орган — залежно від сфери це може бути профільне міністерство, обласна військова адміністрація або інший визначений суб’єкт. Підприємство подає документи, що підтверджують відповідність критеріям, і отримує рішення на визначений строк.</p>
<p>Головне, що варто засвоїти про цей статус: <strong>він не вічний</strong>. Зміни 2026 року прямо передбачали перегляд раніше прийнятих рішень про критичність — підприємства, які не підтвердили статус повторно, втрачали і статус, і разом із ним бронювання працівників. Для бізнесу це означає, що дату перегляду треба тримати в календарі так само, як строк сплати податків.</p>
<p>Практична порада: перевірте, коли саме закінчується ваше рішення про критичність, і хто його видавав. Відповідь «десь у нас є наказ» — не відповідь. Коли бронь спадає, працівник стає призовним наступного дня, а не після листування.</p>`,
