        html: `<p>Найчастіші підстави втрати:</p>
<ul>
<li><b>перехід на заочну чи вечірню форму</b> — право зникає одразу;</li>
<li><b>відрахування</b> з будь-якої причини, включно з академічною неуспішністю;</li>
<li><b>завершення навчання</b> — відстрочка не продовжується на період до вступу на наступний рівень;</li>
<li><b>вступ на рівень, не вищий за здобутий</b>;</li>
<li><b>несвоєчасне поновлення</b> відстрочки перед новим періодом;</li>
<li><b>для викладачів</b> — зменшення навантаження нижче встановленого порога або перехід на сумісництво.</li>
</ul>
<p>Академічна відпустка — окреме питання, яке варто уточнювати індивідуально: вона не є відрахуванням, але й статус здобувача освіти в цей період може оцінюватися по-різному залежно від підстави відпустки й документів закладу.</p>
<p>Головне правило, спільне з усіма іншими підставами: <strong>наявність права без оформленої відстрочки не захищає</strong>. Студент, який має всі підстави, але не оформив відстрочку або не поновив її, перебуває в тому самому становищі, що й особа без підстав. Механізм оскарження відмов — у матеріалі про <a href="/blog/oskarzhennya-rishen-tck/">оскарження рішень ТЦК та СП</a>.</p>`,
