<p>Із цього випливає наслідок, до якого родини зазвичай не готуються: коли <strong>старша дитина досягає 18 років</strong>, кількість дітей до 18 років зменшується до двох — і право на відстрочку за цією підставою припиняється. Відстрочка діє до моменту втрати підстав для її надання, і повноліття однієї дитини саме такою втратою і є.</p>
<table>
<thead><tr><th>Склад родини</th><th>Право на відстрочку за цією підставою</th></tr></thead>
