        h2: "Куди подавати і як поновлювати",
        html: `<p><b>Канал подання.</b> Частина заяв на відстрочку оформлюється через «Резерв+» та центри надання адміністративних послуг, частина — через ТЦК та СП. Канал для цієї підстави варто уточнити перед поданням, бо він змінювався.</p>
<p><b>Підтвердження.</b> За позитивного рішення відомості про відстрочку відображаються у військово-обліковому документі, зокрема електронному. Саме це відображення є підтвердженням — не факт подання заяви й не наявність посвідчення багатодітної родини.</p>
<p><b>Поновлення.</b> Відстрочка надається на визначений строк і потребує поновлення. Для цієї підстави є додатковий фактор: при кожному поновленні заново перевіряється вік дітей, тому поновлення після 18-річчя старшої дитини результату не дасть.</p>
<p>І головне, що діє для всіх підстав: <strong>оформлювати відстрочку потрібно завчасно</strong>. Наявність трьох дітей без оформленої відстрочки від призову не захищає.</p>`,
