        html: `<p>Непридатність до військової служби означає, що стан здоров’я особи унеможливлює її проходження. Висновок ухвалює військово-лікарська комісія за результатами огляду в порядку військово-лікарської експертизи.</p>
<p>Правовою основою висновку є Розклад хвороб — додаток до Положення про військово-лікарську експертизу, затвердженого <strong>наказом Міністра оборони України № 402</strong>. Кожному захворюванню відповідає стаття Розкладу, і вже вона визначає категорію.</p>
<p>Одразу важлива річ про термінологію. У чинній редакції Розкладу хвороб <strong>немає категорії «обмежено придатний»</strong>: її скасували у 2024 році, а осіб із таким статусом направили на повторний огляд. Тому порівняння «непридатність проти обмеженої придатності», яке досі гуляє по форумах, сьогодні порівнює чинну категорію з неіснуючою. Перехідний період ми розбираємо в матеріалі про <a href="/blog/obmezheno-prydatnyy/">статус обмежено придатного</a>.</p>
<p>Супровід здійснюємо в межах практики <a href="/practices/${P}/">військового права</a>.</p>`,
