<p>Висновок комісії — <strong>медичний документ</strong>. Рішення про виключення з військового обліку ухвалює <strong>не ВЛК, а районний (міський) ТЦК та СП</strong> на підставі такого висновку й у порядку, передбаченому Законом України «Про військовий обов’язок і військову службу». Тобто після комісії потрібен ще один крок, і зробити його має людина, а не система.</p>
