<p>Усе тримається на висновку ВЛК, тому саме його об’єктивність і має вирішальне значення. Якщо висновок не відповідає фактичному стану здоров’я — спершу оскаржується він, а не відмова у звільненні. Порядок — у матеріалі про <a href="/blog/vlk-oskarzhennya/">оскарження висновку ВЛК</a>.</p>
