        html: `<p>Розмір одноразової грошової допомоги у разі загибелі (смерті) військовослужбовця становить <strong>15 млн гривень</strong>. Вона виплачується:</p>
<ul>
<li>у разі загибелі (смерті) під час дії воєнного стану;</li>
<li>у разі смерті <strong>протягом трьох років</strong> від поранення, травми, контузії чи каліцтва, пов’язаного із захистом Батьківщини, отриманого під час дії воєнного стану.</li>
</ul>
<p>Три речі, які потрібно знати одразу, бо вони визначають результат.</p>
<p><b>Перше: 15 млн — це сума на всіх отримувачів разом, а не кожному.</b> За загальним правилом вона розподіляється між особами, які мають право на її отримання, рівними частками. Військовослужбовець може за життя визначити інший розподіл — і таке розпорядження має юридичне значення.</p>
<p><b>Друге: строк звернення — три роки.</b> Звернутися за ОГД потрібно не пізніше трьох років з дати актового запису про смерть. Це не формальність: пропущений строк закриває право.</p>
<p><b>Третє: причинний зв’язок має бути належно оформлений.</b> Саме він, а не сам факт смерті, є предметом перевірки. Зв’язок встановлюється висновком військово-лікарської комісії, і формулювання у ньому вирішує справу. Про механіку комісії — у матеріалі про <a href="/blog/vlk-oskarzhennya/">оскарження висновку ВЛК</a>.</p>
<p>Окрема й складна категорія — смерть від захворювання під час служби. Тут практика неоднорідна: Верховний Суд у 2026 році скасовував відмови у таких справах і повертав їх на новий розгляд, тобто питання не вирішується автоматично ні на користь родини, ні проти неї. Якщо смерть настала від хвороби, а не від поранення, справу потрібно будувати окремо й ретельно.</p>`,
