        html: `<p>Про це питають найчастіше, тому відповідаємо прямо, з датами.</p>
<p>У 2025–2026 роках діяли спрощені механізми добровільного повернення: військовослужбовець, який вперше самовільно залишив частину, міг повернутися на службу без притягнення до кримінальної відповідальності, подавши рапорт у встановлений строк. Механізм продовжувався кілька разів. Останній етап — програма для тих, у кого СЗЧ зафіксовано до 12 червня 2026 року, і рапорт приймався <strong>до 20 вересня 2026 року</strong>.</p>
<p><strong>Станом на жовтень 2026 року цей строк уже сплив</strong>, а нового продовження немає. Розраховувати на нього не варто: кожне попереднє продовження ухвалювалося окремим законом, і автоматично воно не поновлюється.</p>
<p>Що це означає практично. Зараз звільнення від кримінальної відповідальності у зв’язку з добровільним поверненням можливе <strong>через суд</strong> у загальному порядку: потрібне клопотання, письмова згода командира військової частини й рішення суду. Це довший і менш гарантований шлях, ніж рапорт за програмою, але він існує.</p>
<p>Важливо не плутати дві речі: добровільне повернення саме по собі <strong>не є автоматичною підставою</strong> для звільнення від відповідальності. Це вагома обставина, яку враховують слідство й суд, і підстава для клопотання — але не автоматичне закриття справи.</p>
<p>Якщо ви стежите за законодавчими ініціативами щодо нового продовження — рішення про повернення варто ухвалювати з юристом і з огляду на чинний, а не очікуваний стан закону.</p>`,
