        h2: "Строки звернення до суду",
        html: `<p>Це найчастіша причина, через яку справа не доходить до розгляду по суті. Строків два, і вони різні.</p>
<table>
<thead><tr><th>Ситуація</th><th>Строк</th><th>З якого моменту</th></tr></thead>
<tbody>
<tr><td>Звернення до суду без досудового оскарження</td><td>шість місяців</td><td>з дня, коли особа дізналася або повинна була дізнатися про порушення свого права</td></tr>
<tr><td>Після оскарження до вищої комісії</td><td>три місяці</td><td>з дня вручення рішення за результатами такого розгляду</td></tr>
</tbody>
</table>
<p>Логіка тут парадоксальна на перший погляд: використання досудового шляху <strong>скорочує</strong> строк звернення до суду. Тому поширена помилка виглядає так — людина оскаржує до вищої комісії, отримує відмову, кілька місяців збирається, а потім виявляє, що тримісячний строк уже сплив, хоча «шість місяців же є».</p>
<p>Пропущений строк можна поновити за поважних причин, і суд оцінює їх за обставинами: проходження військової служби, лікування, перебування за межами України. Але це додатковий бар’єр, який краще не створювати собі самому.</p>
<p>Ще одне, що варто знати одразу: <strong>подання позову не зупиняє дію постанови ВЛК</strong>. Вона чинна, поки суд не визнає її протиправною. Якщо з постанови вже настали наслідки, які не можна відкласти, питання забезпечення позову потрібно ставити окремо й одночасно з позовом.</p>`,
