        html: `<p>Для цивільної особи шлях до комісії лежить через ТЦК: отримання направлення, проходження огляду, висновок про придатність до мобілізації. Для військовослужбовця логіка інша.</p>
<p>Ключові відмінності:</p>
<ul>
<li><strong>Направлення видає командування</strong> військової частини або медична служба частини, а не ТЦК;</li>
<li><strong>Огляд часто відбувається на базі військового госпіталю</strong>, куди військовослужбовця скеровують після лікування або при виявленні захворювання;</li>
<li><strong>Наслідком висновку є не мобілізація, а подальша доля служби</strong> — переведення на посаду, сумісну зі станом здоров’я, або звільнення.</li>
</ul>
<p>Є ще одна відмінність, яка визначає момент огляду. Медичний огляд військовослужбовців, які отримали захворювання, травму, поранення, каліцтво чи контузію, проводиться <strong>при визначеному лікарсько-експертному наслідку</strong> (результаті) — це стан, коли результати обстеження та лікування вже дають підстави винести постанову про ступінь придатності, а подальше лікування не призведе до відновлення придатності до служби (пункт 6.9 наказу Міністра оборони України від 14.08.2008 № 402).</p>
<p>Практично це означає: комісія не ухвалює рішення «посередині» лікування. Якщо вас направили на ВЛК, коли лікування об’єктивно не завершене, це сама по собі підстава наполягати на відстроченні огляду — передчасний висновок майже завжди виявляється на користь служби, а не здоров’я.</p>
<p>Через це помилка з категорією для військовослужбовця має інші наслідки, ніж для цивільного: вона визначає, чи продовжуватиме людина службу в умовах, які їй протипоказані.</p>`,
