<p>Важливо: самовільне залишення частини заради проходження обстеження створює окрему й значно серйознішу проблему — про наслідки читайте в матеріалі про <a href="/blog/szch-stattya-407/">СЗЧ і статтю 407 ККУ</a>. Юридично безвихідної ситуації тут немає: бездіяльність командування оскаржується, а самовільне залишення частини — це вже окремий склад, який нічого не вирішує, але додає кримінальне провадження до медичної проблеми.</p>
