<p>І розмежування, яке потрібно тримати в голові від початку: <strong>ВЛК визначає придатність до військової служби, а група інвалідності встановлюється окремою експертизою</strong> за іншою процедурою та з іншими наслідками для виплат і статусу. Висновок про непридатність не означає автоматично встановлення інвалідності, і навпаки.</p>
