<p>Окремо про штраф. Сплата штрафу не є універсальною умовою зняття: якщо складу порушення немає — наприклад, повістка не вручалася належним чином, — то й підстави для штрафу немає, і розшук скасовується без нього. Плутати ці дві речі невигідно: сплачений штраф у низці випадків читається як визнання порушення.</p>
