<p>Відповідальність за порушення правил військового обліку є адміністративною і накладається <b>на посадових осіб</b> — керівника або відповідальну за облік особу. Розміри штрафів під час дії воєнного стану підвищені, а за повторне порушення протягом року зростають.</p>
