<p>Перше й найважливіше, що треба зрозуміти: <b>відстрочка не виникає сама собою з факту інвалідності в родині</b>. Її потрібно оформити — подати заяву й підтвердні документи. Якщо цього не зробити, особу можуть призвати на загальних підставах, навіть коли вона фактично доглядає за родичем з інвалідністю. Це найдорожча помилка в усій темі.</p>
