        html: `<p>Для частини підстав закон і практика вимагають не просто родинного зв’язку, а <b>фактичного здійснення постійного догляду</b> — або офіційного статусу опікуна.</p>
<p>Що це означає в документах: потрібен медичний висновок про те, що особа <b>потребує постійного стороннього догляду</b>, і підтвердження того, що такий догляд здійснюєте саме ви. Сам факт встановлення групи інвалідності цього не доводить: інвалідність і потреба в постійному догляді — різні медичні висновки.</p>
<p>Тому типовий сценарій відмови виглядає так: заявник подає довідку про інвалідність II групи батька й свідоцтво про народження, і цього достатньо за формальною підставою «батько з інвалідністю II групи». Але коли підстава вимагає догляду, потрібен ще й висновок про потребу в ньому. Перед поданням варто з’ясувати, яка саме підстава стосується вашого випадку, і які документи до неї.</p>
<p><b>Про можливі зміни.</b> У жовтні 2026 року обговорювався законопроєкт, який пропонує зробити <b>необхідність постійного догляду обов’язковою умовою для низки категорій</b>, де зараз достатньо родинного зв’язку: подружжя осіб з інвалідністю I, II та III груп, осіб, чиї батьки мають інвалідність I або II групи, інших родичів. Опікунам недієздатних осіб відстрочку пропонують надавати з урахуванням наявності інших опікунів, а якщо дитину з інвалідністю виховують обоє батьків, один із них за певних обставин може втратити право. Це <b>проєкт, а не чинна норма</b>, але напрям очевидний: формального зв’язку поступово стає недостатньо. Якщо у вас є реальний догляд, документувати його варто вже зараз.</p>`,
