        id: "s1",
        h2: "ВЛК і інвалідність — це різні речі",
        html: `<p>Найпоширеніша плутанина серед поранених військовослужбовців та їхніх родин. Це дві окремі процедури з різними органами, різними наслідками й різними документами.</p>
<table>
<thead><tr><th></th><th>ВЛК</th><th>Встановлення інвалідності</th></tr></thead>
<tbody>
<tr><td>Що визначає</td><td>придатність до військової служби</td><td>стійке порушення функцій організму</td></tr>
<tr><td>Наслідок</td><td>продовження служби або звільнення</td><td>група інвалідності, пенсія, пільги</td></tr>
<tr><td>Хто проводить</td><td>військово-лікарська комісія</td><td>експертна команда в системі охорони здоров’я</td></tr>
<tr><td>Документ</td><td>постанова (висновок) ВЛК</td><td>витяг з рішення експертної команди</td></tr>
<tr><td>Де оскаржується</td><td>вища ВЛК, далі адміністративний суд</td><td>Центр оцінювання функціонального стану особи, далі суд</td></tr>
</tbody>
</table>
<p>Практичний висновок простий: висновок про непридатність до служби <strong>не означає</strong> встановлення інвалідності, а встановлена група <strong>не означає</strong> автоматичного звільнення. Зазвичай поранений військовослужбовець проходить обидві процедури, причому в певній послідовності — спочатку ВЛК, потім оцінювання. І саме ця послідовність визначає, що буде написано в документі про причину інвалідності.</p>
<p>Із цієї різниці випливає й різниця в предметі оскарження. Якщо не влаштовує група — оскаржується рішення експертної команди. Якщо не влаштовує формулювання причини інвалідності — оскаржується висновок ВЛК, бо саме він є джерелом цього формулювання. Помилка у виборі предмета оскарження коштує часу і зазвичай завершується відмовою з формальних підстав. Загальний огляд напряму ми наводимо у <a href="/blog/${C}/">блозі про військове право</a>, а супровід здійснюємо в межах практики <a href="/practices/${P}/">військового права LEGIUS</a>.</p>`,
