<li><strong>Оскаржують не той документ.</strong> Людина незадоволена формулюванням причини інвалідності, але оскаржує рішення експертної команди. Команда формулювання не визначала — вона взяла його з висновку ВЛК. Результат: відмова з формальних підстав і втрачений час.</li>
