        h2: "Виплати за новими контрактами",
        html: `<p>Структура виплат за новими контрактами відрізняється від звичайного грошового забезпечення: значна частина прив’язана не до посади, а до фактично виконаних завдань.</p>
<p><b>Піхотно-штурмовий контракт.</b> Базова ставка 20 000 ₴ плюс додаткові винагороди за принципом «10/20/40»:</p>
<ul>
<li><b>10 000 ₴ за день</b> — виконання завдань безпосередньо на бойових позиціях на рівні взводного опорного пункту;</li>
<li><b>20 000 ₴ за день</b> — ударно-пошукові дії: знищення малих груп противника, розвідка, евакуація, повернення позицій;</li>
<li><b>40 000 ₴ за день</b> — штурмові дії з просуванням уперед.</li>
</ul>
<p>За розрахунками Міністерства оборони середня виплата за таким контрактом становить близько <b>300 000 ₴ на місяць</b>, максимальна — <b>не більше 460 000 ₴</b>.</p>
<p><b>Бойовий контракт</b> (БпЛА, НРК, РЕБ, артилерія): від 30 000 до 120 000 ₴ на місяць — чим ближче до першої лінії, тим вище.</p>
<p>Загальні правила грошового забезпечення теж варто знати. Воно виплачується <b>до 20 числа поточного місяця за минулий</b>; якщо кошти надійшли до частини пізніше — протягом трьох днів після надходження. Надбавка за вислугу років зростає зі стажем: 25 % при вислузі від 1 до 5 років, 30 % — від 5 до 10. Додаткова винагорода 10 000 ₴ передбачена для тих, хто не бере участі в бойових діях і не отримує бойових винагород 30 000, 50 000 або 100 000 ₴; вона не виплачується під час відпустки, але зберігається під час лікування — а при лікуванні після поранення, пов’язаного із захистом Батьківщини, передбачена винагорода 100 000 ₴.</p>
<p>Попередження: суми, які озвучують рекрутери, — це максимуми за умови фактичної участі в бойових діях щодня. Реальна виплата залежить від кількості таких днів, і саме це питання варто ставити до підписання, а не після.</p>`,
