        html: `<p>Контракт — це договір, і його текст має значення. Що читати уважно:</p>
<ol>
<li><b>Строк</b> — конкретна кількість місяців, а не «на період дії воєнного стану». Якщо в тексті стоїть другий варіант, це не новий контракт із чітким строком.</li>
<li><b>Посада й підрозділ</b> — чи зафіксовані вони в контракті, чи лишені на пізніше. Обіцянка «потім переведемо» юридичної сили не має.</li>
<li><b>Належність посади до переліків</b>, за якими діють підвищені виплати. Виплати «10/20/40» прив’язані до посад із затверджених Міноборони переліків, а не до назви підрозділу.</li>
<li><b>Підстави дострокового припинення</b> — повний перелік, а не посилання «відповідно до законодавства».</li>
<li><b>Умови й порядок переведення</b> на інші посади протягом строку.</li>
<li><b>Розрахунок відстрочки</b> — як зараховується ваша попередня служба, якщо ви її мали.</li>
</ol>
<p>Найчастіша помилка — підписати, не прочитавши, покладаючись на усні пояснення. Після підписання змінити умови односторонньо неможливо, а розбіжність між обіцяним і написаним вирішується на користь написаного.</p>
<p>Якщо ви чинний військовослужбовець і розглядаєте перехід на новий контракт, варто порівняти два сценарії в цифрах: що ви отримуєте за новим контрактом і яка відстрочка з нього виходить проти вашого поточного становища.</p>`,
